ruleBookInfo.coverUrl:
@js:
var doc = org.jsoup.Jsoup.parse(result);
var img = doc.select('main img[alt$=小说封面]').first();
if (img == null) { img = doc.select('main img[alt$=照片]').first(); }
img ? ('https://s.bailushuyuan.org' + img.attr('src')) : ''

ruleBookInfo.intro:
@js:
var doc = org.jsoup.Jsoup.parse(result);
var all = doc.getAllElements();
var ol = doc.select('ol.text-body-tertiary').first();
var olIdx = (ol != null) ? all.indexOf(ol) : -1;
var ps = doc.select('p.mb-2');
var txt = [];
for (var j = 0; j < ps.size(); j++) {
  var pi = all.indexOf(ps.get(j));
  if (olIdx < 0 || pi < olIdx) { txt.push(ps.get(j).text()); }
}
txt.join('\n');

