ruleToc.chapterList:
@js:
var doc = org.jsoup.Jsoup.parse(result);
var ols = doc.select('ol.text-body-tertiary li a');
var mainAs = doc.select('main a[title]');
var list = [];
if (ols.size() > 0) {
  for (var i = 0; i < ols.size(); i++) {
    list.push(JSON.stringify({title: ols.get(i).text(), url: 'https://s.bailushuyuan.org' + ols.get(i).attr('href')}));
  }
} else {
  for (var j = 0; j < mainAs.size(); j++) {
    list.push(JSON.stringify({title: mainAs.get(j).attr('title'), url: 'https://s.bailushuyuan.org' + mainAs.get(j).attr('href')}));
  }
}
list;

searchUrl:
@js:
var any = '';
var exact = '';
var enc = encodeURIComponent(key);
for (var i = 1; i <= 9; i++) {
  var u = 'https://s.bailushuyuan.org/novel/traditional/categories/' + i + '?name_cont=' + enc;
  try {
    var body = java.ajax(u);
    if (body.indexOf('row gx-1 gy-3 mb-3 text-center') !== -1) {
      if (!any) { any = u; }
      if (body.indexOf('href="/' + enc + '"') !== -1) { exact = u; break; }
    }
  } catch(e) {}
}
exact || any || ('https://s.bailushuyuan.org/novel/traditional/categories/1?name_cont=' + enc);
